 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # A solid colored line is the wall; the other objects slide toward it.
    wall_row = next((r for r, row in enumerate(g) if len(set(row)) == 1 and row[0] != 0), None)
    if wall_row is None:
        raise ValueError('expected a solid horizontal wall')
    direction = -1 if wall_row == 0 else 1
    wall_color = g[wall_row][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or g[r][c] == wall_color or (r, c) in seen:
                continue
            color = g[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and g[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            objects.append((color, cells))
    # Process the objects nearest the wall first, allowing each to slide until blocked.
    objects.sort(key=lambda obj: (min(r for r,c in obj[1]) if direction < 0 else -max(r for r,c in obj[1])))
    occupied = {(r,c) for r in range(h) for c in range(w) if g[r][c] != 0}
    for color, cells in objects:
        occupied.difference_update(cells)
        cells = list(cells)
        while True:
            nxt = [(r + direction, c) for r,c in cells]
            if any(r < 0 or r >= h or c < 0 or c >= w or (r,c) in occupied for r,c in nxt):
                break
            cells = nxt
        for r,c in cells:
            g[r][c] = color
            occupied.add((r,c))
    return g
